async function getData(slug) {
  const posts = postsData;
  const decodedSlug = decodeURIComponent(slug);
  const fullSlugPath = `/blog/${decodedSlug}`;
  const foundPost = posts.find((post) => post.slug === fullSlugPath);
  return foundPost || null;
}
